# hypothesis: a TypeIs[Source] guard narrows a runtime-registered class to Source, while a static checker rejects passing that registered class where Source is required; a Literal parameter is also checked.
from abc import ABC, abstractmethod
from typing import Literal, TypeIs, assert_type, reveal_type


class Source(ABC):
    @property
    @abstractmethod
    def name(self) -> str:
        raise NotImplementedError


class Fixed:
    @property
    def name(self) -> str:
        return 'fixed'


Source.register(Fixed)


class AttrSource(Source):
    name = 'attr'


def is_source(x: object) -> TypeIs[Source]:
    return isinstance(x, Source)


def label(x: AttrSource | Fixed) -> str:
    if is_source(x):
        reveal_type(x)
        return x.name
    return 'none'


def need_source(s: Source) -> str:
    return s.name


def bad(f: Fixed) -> str:
    return need_source(f)  # expect-error: Fixed is not statically a Source


def mode(flag: Literal['on', 'off']) -> int:
    return {'on': 1, 'off': 0}[flag]


assert_type(label(AttrSource()), str)
assert label(AttrSource()) == 'attr'
assert label(Fixed()) == 'fixed'
assert bad(Fixed()) == 'fixed'
assert issubclass(Fixed, Source)
assert mode('on') == 1
try:
    mode('maybe')  # expect-error: 'maybe' is not a Literal member
except KeyError as exc:
    print('runtime:', type(exc).__name__)
